// From an analysis to the generated files (LIB-19): indexes, interfaces, types, reachable paths, arrows.
import { surfaceOf, type Analysis, type ModuleNode } from './analyze.ts'
import { arrowsFile, folderOf, join, surfaceKinds, type Kind } from './names.ts'

export interface GeneratedFile {
  /** Relative to the compiled root. */
  readonly path: string
  readonly text: string
}

export interface GenerateOptions {
  /** The compiled root, relative to the repository (for the rules of the graph), e.g. `packages/domains/src`. */
  readonly rootFromRepo: string
}

const header = "// Generated by the library's compiler (LIB-19): do not edit.\n"

const byText = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0)
const nameOf = (folder: string): string => folder.slice(folder.lastIndexOf('/') + 1)
const quote = (text: string): string => `'${text}'`
const pascal = (name: string): string => name.charAt(0).toUpperCase() + name.slice(1)
const local = (name: string, kind: Kind | 'folder'): string => `${name}$${kind}`
const upTo = (folder: string): string =>
  folder === '' ? './' : '../'.repeat(folder.split('/').length)

export function generate(analysis: Analysis, options: GenerateOptions): readonly GeneratedFile[] {
  const files: GeneratedFile[] = []
  for (const folder of ['', ...analysis.folders]) files.push(indexOf(analysis, folder))
  for (const node of analysis.nodes) {
    if (node.exports.schema.length > 0) files.push(typesOf(node))
  }
  for (const domain of analysis.domains)
    files.push(reachableOf(analysis, domain.path, domain.consumes))
  files.push({ path: arrowsFile, text: arrowsOf(analysis, options.rootFromRepo) })
  return files.sort((a, b) => byText(a.path, b.path))
}

function entriesOf(node: ModuleNode): readonly string[] {
  const { command, predicate, schema } = node.exports
  const n = node.name
  const entries: [string, string][] = []
  for (const name of command)
    entries.push([
      name,
      `{ kind: 'command', run: ${local(n, 'command')}.${name}, input: ${local(n, 'schema')}.${name} }`,
    ])
  for (const name of predicate) {
    const fields = `value: ${local(n, 'predicate')}.${name}, input: ${local(n, 'schema')}.${name}`
    entries.push([name, `{ kind: 'predicate', ${fields}, reads: ${local(n, 'reads')}.${name} }`])
  }
  for (const name of schema.filter((s) => !command.includes(s) && !predicate.includes(s)))
    entries.push([name, `{ kind: 'schema', schema: ${local(n, 'schema')}.${name} }`])
  return entries.sort(([a], [b]) => byText(a, b)).map(([name, value]) => `${name}: ${value},`)
}

function indexOf(analysis: Analysis, folder: string): GeneratedFile {
  const subfolders = analysis.folders
    .filter((f) => f !== folder && folderOf(f) === folder)
    .map(nameOf)
  const nodes = analysis.nodes.filter((n) => n.folder === folder)
  const imports: string[] = []
  for (const sub of subfolders)
    imports.push(`import { node as ${local(sub, 'folder')} } from './${sub}/index.ts'`)
  for (const node of nodes) {
    for (const kind of node.kinds)
      imports.push(`import * as ${local(node.name, kind)} from './${node.name}.${kind}.ts'`)
  }
  const children = [...new Set([...subfolders, ...nodes.map((n) => n.name)])].sort(byText)
  const body = children.map((child) => {
    const node = nodes.find((n) => n.name === child)
    const hasFolder = subfolders.includes(child)
    if (node === undefined) return `${child}: ${local(child, 'folder')},`
    const spread = hasFolder ? [`...${local(child, 'folder')},`] : []
    return `${child}: {\n${[...spread, ...entriesOf(node)].join('\n')}\n},`
  })
  const value = `{\n${body.join('\n')}\n} as const`
  const lines = [header, ...imports.sort(byText), '']
  if (folder !== '') {
    lines.push(`export const node = ${value}`)
  } else {
    const domainPaths = analysis.domains.map((d) => quote(d.path))
    const flat = analysis.components.map((c) => {
      const access = c.path
        .split('/')
        .map((s) => `[${quote(s)}]`)
        .join('')
      return `readonly ${quote(c.path)}: Tree${access}`
    })
    lines.push(
      '/** Every domain and its components, by path (LIB-19). */',
      `export const tree = ${value}`,
      '',
      '/** The tree interface: the type of the root index. */',
      'export type Tree = typeof tree',
      '',
      '/** The paths of the domains. */',
      `export type DomainPath = ${domainPaths.length > 0 ? domainPaths.join(' | ') : 'never'}`,
      '',
      '/** The flat interface: every component under its path. */',
      flat.length > 0
        ? `export interface Flat {\n${flat.join('\n')}\n}`
        : 'export type Flat = Record<never, never>',
    )
  }
  return { path: join(folder, 'index.ts'), text: `${lines.join('\n')}\n` }
}

function typesOf(node: ModuleNode): GeneratedFile {
  const types = node.exports.schema.map(
    (name) => `export type ${pascal(name)} = z.infer<typeof schema.${name}>`,
  )
  const text = [
    header,
    "import type * as z from 'zod'",
    `import type * as schema from './${node.name}.schema.ts'`,
    '',
    ...types,
    '',
  ].join('\n')
  return { path: join(node.folder, `${node.name}.types.ts`), text }
}

function reachableOf(
  analysis: Analysis,
  domain: string,
  consumes: readonly string[],
): GeneratedFile {
  const own = analysis.components.filter((c) => c.domain === domain)
  const surface = consumes.flatMap((consumed) => surfaceOf(analysis, consumed))
  const paths = [...own, ...surface].map((c) => quote(c.path)).sort(byText)
  const text = [
    header,
    `import type { Flat } from '${upTo(domain)}index.ts'`,
    '',
    '/** The paths this domain may name: its own and the surface of the domains it consumes (LIB-21). */',
    `export type Reachable = Pick<Flat, ${paths.length > 0 ? paths.join(' | ') : 'never'}>`,
    '',
  ].join('\n')
  return { path: join(domain, 'domain.paths.ts'), text }
}

const escape = (text: string): string => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

function arrowsOf(analysis: Analysis, rootFromRepo: string): string {
  const root = rootFromRepo === '' ? '^' : `^${escape(rootFromRepo)}/`
  const surface = `\\.(${surfaceKinds.join('|')})\\.ts$`
  const rules = analysis.domains.map((domain) => {
    const allowed = [
      `${root}${escape(domain.path)}/`,
      `${root}library/index\\.ts$`,
      ...domain.consumes.map((c) => `${root}${escape(c)}/.*${surface}`),
    ]
    const consumed =
      domain.consumes.length > 0
        ? `the surface of ${domain.consumes.join(', ')}`
        : 'no other domain'
    return [
      '{',
      `name: ${JSON.stringify(`domain:${domain.path}`)},`,
      `comment: ${JSON.stringify(`${domain.path} imports the library, itself and ${consumed} (GR-1, LIB-21)`)},`,
      "severity: 'error',",
      `from: { path: ${JSON.stringify(`${root}${escape(domain.path)}/`)}, pathNot: ${JSON.stringify('/domain(\\.paths)?\\.ts$')} },`,
      `to: { path: ${JSON.stringify(root)}, pathNot: [${allowed.map((a) => JSON.stringify(a)).join(', ')}] },`,
      '},',
    ].join('\n')
  })
  return [
    header,
    '// The arrows of the graph, from the markers of the domains (LIB-14, LIB-21).',
    `module.exports = [\n${rules.join('\n')}\n]`,
    '',
  ].join('\n')
}
